## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/portalHypertensionLogic.ts`

```typescript
/**
 * Portal Hypertension & Portal Vein Complications Clinical Compass™
 * Logic Engine
 *
 * Guidelines:
 *   - Baveno VII Consensus (2022) + Baveno VII Expanded Consensus (2024 Update)
 *   - AASLD Practice Guidance: Portal Hypertension (2023/2024)
 *   - EASL Clinical Practice Guidelines: Decompensated Cirrhosis (2023)
 *   - EASL Clinical Practice Guidelines: Vascular Diseases of the Liver (2024)
 *   - SIR Practice Guidelines: TIPS (2024)
 *   - ACG Clinical Guideline: Hepatic Encephalopathy (2022)
 *   - AASLD/EASL: Portal Vein Thrombosis in Cirrhosis (2024)
 *
 * Key decisions:
 *   1. Portal Vein Thrombosis (PVT) — classification, anticoagulation, TIPS
 *   2. Variceal Bleeding — primary prophylaxis, acute bleed management, secondary prophylaxis
 *   3. Ascites — diuretics, LVP, TIPS, transjugular hepatic biopsy
 *   4. Hepatic Encephalopathy — precipitant identification, lactulose/rifaximin, TIPS contraindication
 *   5. Hepatorenal Syndrome — terlipressin, norepinephrine, TIPS bridge to transplant
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type PVTExtent =
  | 'none'
  | 'partial_main' // <50% occlusion of main portal vein
  | 'complete_main' // ≥50% or complete occlusion of main portal vein
  | 'extending_smv' // Extending into superior mesenteric vein
  | 'cavernous_transformation'; // Chronic — cavernous transformation

export type PVTAcuity = 'acute' | 'subacute' | 'chronic' | 'unknown';

export type ChildPughClass = 'A' | 'B' | 'C';

export type MELDCategory =
  | 'low' // MELD <10
  | 'moderate' // MELD 10–14
  | 'high' // MELD 15–19
  | 'very_high'; // MELD ≥20

export type VaricesGrade =
  | 'none'
  | 'small' // <5mm, no red wale marks
  | 'medium' // 5–10mm
  | 'large' // >10mm or occupying >1/3 of lumen
  | 'not_screened';

export type AscitesGrade =
  | 'none'
  | 'grade1' // Detectable only by ultrasound
  | 'grade2' // Moderate, visible distension
  | 'grade3' // Large/tense ascites
  | 'refractory'; // Refractory to diuretics

export type HEGrade =
  | 'none'
  | 'minimal' // Covert HE — detectable only by psychometric testing
  | 'grade1' // Trivial lack of awareness, euphoria/anxiety, shortened attention span
  | 'grade2' // Lethargy, disorientation, personality change
  | 'grade3' // Somnolence, confusion, gross disorientation
  | 'grade4'; // Coma

export type PrimaryScenario =
  | 'pvt_management' // Portal vein thrombosis
  | 'primary_prophylaxis' // Prevention of first variceal bleed
  | 'acute_variceal_bleed' // Active or recent variceal hemorrhage
  | 'secondary_prophylaxis' // Prevention of re-bleed after first bleed
  | 'ascites_management' // Ascites / refractory ascites
  | 'hepatic_encephalopathy' // HE management
  | 'hepatorenal_syndrome'; // HRS-AKI

export interface PortalHypertensionInput {
  // ── Patient demographics ──────────────────────────────────────────────────
  ageYears: number;
  /** Primary clinical scenario driving this consult */
  primaryScenario: PrimaryScenario;

  // ── Liver disease characterization ───────────────────────────────────────
  hasCirrhosis: boolean;
  childPughClass: ChildPughClass;
  meldCategory: MELDCategory;
  /** Clinically significant portal hypertension (HVPG ≥10 mmHg or indirect evidence) */
  hasClinicallySignificantPH: boolean;
  /** HVPG measured (mmHg) — if available */
  hvpgMmHg?: number;
  /** Baveno VII non-invasive criteria met: LSM <20 kPa + platelets >150k → rules out CSPH */
  bavenoVIICriteriaMet?: boolean;

  // ── Portal vein thrombosis ────────────────────────────────────────────────
  pvtExtent: PVTExtent;
  pvtAcuity: PVTAcuity;
  /** Intestinal ischemia signs (acute mesenteric ischemia) */
  hasIntestinalIschemia: boolean;
  /** Known thrombophilia (JAK2, antiphospholipid, factor V Leiden, etc.) */
  hasThrombophilia: boolean;
  /** Prior anticoagulation for PVT */
  isOnAnticoagulation: boolean;
  /** Contraindication to anticoagulation */
  hasAnticoagulationContraindication: boolean;

  // ── Varices ───────────────────────────────────────────────────────────────
  varicesGrade: VaricesGrade;
  /** Red wale marks or red spots on varices (high-risk stigmata) */
  hasRedWaleMarks: boolean;
  /** Active variceal bleeding at time of assessment */
  hasActiveVaricealBleeding: boolean;
  /** Prior variceal bleed (for secondary prophylaxis) */
  hasPriorVaricealBleeding: boolean;
  /** NSBB already prescribed */
  isOnNSBB: boolean;
  /** Prior endoscopic band ligation (EBL) */
  hasPriorEBL: boolean;
  /** Gastric varices present (GOV1, GOV2, IGV1) */
  hasGastricVarices: boolean;
  /** Gastric varices type */
  gastricVaricesType?: 'GOV1' | 'GOV2' | 'IGV1';

  // ── Ascites ───────────────────────────────────────────────────────────────
  ascitesGrade: AscitesGrade;
  /** Spontaneous bacterial peritonitis (SBP) — current or prior */
  hasSBP: boolean;
  /** Prior SBP episode */
  hasPriorSBP: boolean;
  /** Serum-ascites albumin gradient (SAAG) ≥1.1 g/dL */
  saagHighGradient: boolean;
  /** Ascitic fluid protein <1.5 g/dL (SBP prophylaxis indicator) */
  ascitesProteinLow: boolean;
  /** Diuretic-refractory (failed spironolactone 400mg + furosemide 160mg) */
  isDiureticRefractory: boolean;
  /** Diuretic-intolerant (hyponatremia, encephalopathy, renal impairment) */
  isDiureticIntolerant: boolean;

  // ── Hepatic Encephalopathy ────────────────────────────────────────────────
  heGrade: HEGrade;
  /** Identified precipitant (infection, GI bleed, constipation, electrolyte, drugs) */
  hePrecipitantIdentified: boolean;
  hePrecipitant?: 'infection' | 'gi_bleed' | 'constipation' | 'electrolyte' | 'drugs' | 'dehydration' | 'other';
  /** Prior HE episode (recurrent HE) */
  hasPriorHEEpisode: boolean;
  /** On lactulose */
  isOnLactulose: boolean;
  /** On rifaximin */
  isOnRifaximin: boolean;

  // ── Hepatorenal Syndrome ──────────────────────────────────────────────────
  hasHRS: boolean;
  /** HRS-AKI (acute) vs HRS-CKD (chronic) */
  hrsType?: 'HRS_AKI' | 'HRS_CKD';
  /** Creatinine at presentation (mg/dL) */
  creatinineMgDl?: number;

  // ── TIPS candidacy ────────────────────────────────────────────────────────
  /** Prior TIPS placed */
  hasPriorTIPS: boolean;
  /** TIPS contraindications */
  hasTIPSContraindication: boolean;
  tipsContraindications?: Array<'heart_failure' | 'severe_pulmonary_htn' | 'uncontrolled_infection' | 'biliary_obstruction' | 'polycystic_liver' | 'he_grade3_4'>;

  // ── Transplant ────────────────────────────────────────────────────────────
  isTransplantCandidate: boolean;
  isListedForTransplant: boolean;
}

export interface PortalHypertensionRecommendation {
  primaryRecommendation: string;

  // PVT
  pvtManagement: string;
  anticoagulationPlan: string;

  // Varices
  varicesProphylaxis: string;
  acuteBleedManagement: string;
  secondaryProphylaxis: string;

  // Ascites
  ascitesManagement: string;
  sbpProphylaxis: string;

  // HE
  heManagement: string;

  // HRS
  hrsManagement: string;

  // TIPS
  tipsIndication: string;
  tipsContraindicationAssessment: string;

  // General
  transplantConsideration: string;
  monitoringPlan: string;
  urgentFlags: string[];
  recommendedAgents: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

// ─── Main Logic Function ──────────────────────────────────────────────────────

export function assessPortalHypertension(
  input: PortalHypertensionInput
): PortalHypertensionRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];
  const recommendedAgents: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasActiveVaricealBleeding) {
    urgentFlags.push(
      'ACTIVE VARICEAL BLEEDING: Airway protection (intubate if GCS ≤8 or massive bleed), IV octreotide 50mcg bolus then 25–50mcg/hr infusion, IV ceftriaxone 1g/day (7-day course), urgent upper endoscopy within 12 hours (ideally <6h). Target Hgb 7–8 g/dL (restrictive transfusion — Baveno VII Strong Recommendation). TIPS within 72h if Child-Pugh B/C or HVPG ≥20 mmHg (pre-emptive TIPS).'
    );
    nextSteps.push(
      'Urgent upper endoscopy (within 12h)',
      'IV octreotide infusion',
      'IV ceftriaxone 1g/day x7 days',
      'ICU admission',
      'Hepatology + IR + GI consult'
    );
  }

  if (input.hasIntestinalIschemia) {
    urgentFlags.push(
      'INTESTINAL ISCHEMIA with PVT: Emergency surgical/IR consultation required. Anticoagulation must be started immediately (LMWH or UFH). CT angiography to assess mesenteric vein involvement. Surgical resection if bowel necrosis.'
    );
    nextSteps.push('Emergency surgery/IR consultation', 'CT angiography of mesenteric vessels', 'Immediate anticoagulation');
  }

  if (input.hasSBP) {
    urgentFlags.push(
      'SPONTANEOUS BACTERIAL PERITONITIS: IV cefotaxime 2g Q8h x5 days (or ceftriaxone 1g/day). IV albumin 1.5g/kg on day 1 + 1g/kg on day 3 (prevents HRS — SORT trial). Diagnostic paracentesis to confirm (PMN ≥250/mm³). After resolution: indefinite norfloxacin 400mg/day or TMP-SMX for secondary SBP prophylaxis.'
    );
    nextSteps.push('Diagnostic paracentesis (PMN count)', 'IV cefotaxime or ceftriaxone', 'IV albumin protocol');
  }

  if (input.heGrade === 'grade3' || input.heGrade === 'grade4') {
    urgentFlags.push(
      `SEVERE HEPATIC ENCEPHALOPATHY (Grade ${input.heGrade === 'grade3' ? '3' : '4'}): Airway protection, ICU admission. Identify and treat precipitant urgently. Lactulose via NG tube if unable to take PO. Rifaximin 550mg BID. Avoid TIPS in uncontrolled HE Grade 3–4 (absolute contraindication). Liver transplant evaluation if refractory.`
    );
  }

  if (input.hasHRS && input.hrsType === 'HRS_AKI') {
    urgentFlags.push(
      'HEPATORENAL SYNDROME — ACUTE (HRS-AKI): Hold nephrotoxins/diuretics. IV albumin 1g/kg/day (max 100g) x2 days. Terlipressin 0.5–2mg IV Q4–6h (preferred — CONFIRM trial) or norepinephrine 0.5–3mg/hr + albumin if terlipressin unavailable. Liver transplant evaluation urgently — HRS-AKI has 50% 30-day mortality without transplant.'
    );
    nextSteps.push('Hold diuretics and nephrotoxins', 'IV albumin challenge', 'Terlipressin or norepinephrine', 'Urgent transplant evaluation');
  }

  if (input.meldCategory === 'very_high' && input.isTransplantCandidate && !input.isListedForTransplant) {
    urgentFlags.push(
      'MELD ≥20: Urgent liver transplant evaluation and listing. All interventions (TIPS, anticoagulation, paracentesis) are bridges to transplant — do not delay listing.'
    );
  }

  // ─── PVT Management ───────────────────────────────────────────────────────
  let pvtManagement = '';
  let anticoagulationPlan = '';

  if (input.pvtExtent === 'none') {
    pvtManagement = 'No portal vein thrombosis identified. Routine surveillance per cirrhosis guidelines (6-monthly ultrasound + AFP).';
    anticoagulationPlan = 'No anticoagulation indicated for PVT. Assess for other anticoagulation indications (AF, DVT, etc.) separately.';
  } else if (input.pvtExtent === 'cavernous_transformation') {
    pvtManagement =
      'Chronic PVT with cavernous transformation: recanalization is not feasible. Focus on portal hypertension complications management. ' +
      'TIPS is technically challenging but may be possible via transhepatic or trans-splenic approach at experienced centers. ' +
      'Anticoagulation for cavernous transformation: benefit uncertain — assess on case-by-case basis (thrombophilia, progression risk).';
    anticoagulationPlan =
      'Cavernous transformation: anticoagulation does not reverse established cavernoma. ' +
      'Consider anticoagulation only if: active thrombophilia, progressive thrombosis, or pre-transplant (to maintain mesenteric vein patency for surgical anastomosis).';
  } else {
    // Acute/subacute/partial/complete PVT
    const isHighRiskPVT =
      input.pvtExtent === 'complete_main' ||
      input.pvtExtent === 'extending_smv' ||
      input.pvtAcuity === 'acute';

    pvtManagement =
      input.pvtAcuity === 'acute'
        ? 'Acute PVT (≤6 months): anticoagulation is strongly recommended — recanalization rates 40–80% with early treatment (AASLD 2024, EASL Vascular 2024). ' +
          'Start LMWH (enoxaparin 1mg/kg SC BID) or direct oral anticoagulant (rivaroxaban, apixaban — preferred in non-cirrhotic PVT). ' +
          'In cirrhosis: LMWH preferred (DOACs under-studied in Child-Pugh B/C). Treat for minimum 6 months; indefinitely if thrombophilia or recurrent.'
        : input.pvtAcuity === 'subacute'
        ? 'Subacute PVT (6 weeks–6 months): anticoagulation still beneficial — partial recanalization achievable. LMWH or DOAC. ' +
          'Reassess with Doppler ultrasound at 3 months to assess response.'
        : 'Chronic PVT (>6 months): anticoagulation less likely to achieve recanalization but prevents progression. ' +
          'Weigh bleeding risk (varices) vs thrombosis progression. Baveno VII: anticoagulate if thrombophilia, pre-transplant, or progressive thrombosis.';

    if (input.hasAnticoagulationContraindication) {
      pvtManagement +=
        ' ANTICOAGULATION CONTRAINDICATED: Consider TIPS if anatomy permits (TIPS creates portosystemic shunt, reduces portal pressure, and may allow recanalization). Discuss risks/benefits with multidisciplinary team.';
    }

    anticoagulationPlan = input.hasAnticoagulationContraindication
      ? 'Anticoagulation contraindicated. Evaluate TIPS candidacy. Multidisciplinary review required.'
      : input.hasCirrhosis && (input.childPughClass === 'B' || input.childPughClass === 'C')
      ? 'Cirrhotic PVT (Child-Pugh B/C): LMWH enoxaparin 1mg/kg SC BID preferred over DOACs (limited data in decompensated cirrhosis). ' +
        'Monitor anti-Xa levels. Transition to warfarin (INR 2–3) or rivaroxaban 15mg BID if stable. Duration: minimum 6 months, reassess at 3 months with Doppler.'
      : 'Non-cirrhotic or compensated cirrhotic PVT: rivaroxaban 15mg BID x21 days then 20mg/day (DOAC preferred — AASLD 2024) or apixaban 10mg BID x7 days then 5mg BID. ' +
        'Thrombophilia workup: JAK2 V617F, antiphospholipid antibody, factor V Leiden, prothrombin G20210A, protein C/S, antithrombin. Duration: minimum 6 months; indefinitely if thrombophilia confirmed.';

    if (isHighRiskPVT) {
      recommendedAgents.push(
        'Enoxaparin 1mg/kg SC BID (preferred in Child-Pugh B/C cirrhosis)',
        'Rivaroxaban 15mg BID x21 days then 20mg/day (non-cirrhotic or compensated)',
        'Apixaban 10mg BID x7 days then 5mg BID (alternative DOAC)'
      );
    }
  }

  // ─── Varices — Primary Prophylaxis ────────────────────────────────────────
  let varicesProphylaxis = '';

  if (input.varicesGrade === 'none' || input.varicesGrade === 'small') {
    if (input.bavenoVIICriteriaMet) {
      varicesProphylaxis =
        'Baveno VII criteria met (LSM <20 kPa + platelets >150k): varices unlikely to be clinically significant. ' +
        'Endoscopy can be safely avoided. Repeat non-invasive assessment in 2 years (or annually if ongoing liver injury).';
    } else if (input.varicesGrade === 'small' && !input.hasRedWaleMarks && input.childPughClass === 'A') {
      varicesProphylaxis =
        'Small varices without red wale marks in Child-Pugh A: NSBB (carvedilol 6.25mg/day, titrate to 12.5mg/day) or surveillance endoscopy every 1–2 years. ' +
        'Baveno VII: carvedilol preferred over propranolol (superior portal pressure reduction). No EBL for small varices.';
      recommendedAgents.push('Carvedilol 6.25mg/day → 12.5mg/day (preferred NSBB — Baveno VII)');
    } else {
      varicesProphylaxis =
        'No varices or small varices: surveillance upper endoscopy every 2–3 years (compensated cirrhosis) or every 1–2 years (decompensated). ' +
        'Non-invasive alternatives: Baveno VII criteria, platelet count + LSM algorithm.';
    }
  } else if (input.varicesGrade === 'medium' || input.varicesGrade === 'large' || input.hasRedWaleMarks) {
    varicesProphylaxis =
      'Medium/large varices or high-risk stigmata (red wale marks): primary prophylaxis REQUIRED. ' +
      'Option 1: Non-selective beta-blocker — carvedilol 6.25mg/day (preferred) or propranolol 20mg BID titrated to HR 55–60 bpm or max tolerated dose. ' +
      'Option 2: Endoscopic band ligation (EBL) every 2–4 weeks until eradication — equivalent to NSBB but requires repeated endoscopy. ' +
      'Baveno VII: NSBB preferred over EBL as first-line (avoids procedural risk, systemic benefits including reduced bacterial translocation). ' +
      'NSBB + EBL combination: NOT recommended for primary prophylaxis (no added benefit, increased adverse events).';
    recommendedAgents.push(
      'Carvedilol 6.25mg/day → 12.5mg/day (preferred NSBB for primary prophylaxis)',
      'Propranolol 20mg BID → titrate to HR 55–60 bpm (alternative NSBB)',
      'Nadolol 40mg/day (alternative — once daily dosing)'
    );
  } else if (input.varicesGrade === 'not_screened') {
    varicesProphylaxis =
      'Varices not screened: upper endoscopy required. Apply Baveno VII non-invasive criteria first: ' +
      'if LSM <20 kPa AND platelets >150k → endoscopy can be safely avoided. Otherwise, perform EGD.';
    nextSteps.push('Upper endoscopy for variceal screening (or apply Baveno VII criteria)');
  }

  // ─── Acute Variceal Bleed Management ──────────────────────────────────────
  let acuteBleedManagement = '';

  if (input.hasActiveVaricealBleeding || input.hasPriorVaricealBleeding) {
    acuteBleedManagement =
      'ACUTE VARICEAL BLEED PROTOCOL (Baveno VII 2022 + AASLD 2024):\n' +
      '1. RESUSCITATION: Restrictive transfusion (Hgb target 7–8 g/dL — TRANSFUSE trial). Avoid over-transfusion (worsens portal pressure). Correct coagulopathy cautiously (INR is unreliable in cirrhosis).\n' +
      '2. VASOACTIVE THERAPY: IV octreotide 50mcg bolus then 25–50mcg/hr x5 days (or terlipressin 2mg Q4h x48h then 1mg Q4h — superior to octreotide, not available in all countries).\n' +
      '3. ANTIBIOTICS: IV ceftriaxone 1g/day x7 days (reduces bacterial infections, rebleeding, and mortality — Baveno VII Strong Recommendation).\n' +
      '4. ENDOSCOPY: Within 12 hours (ideally <6h in unstable patients). EBL is first-line for esophageal varices. Tissue adhesive (cyanoacrylate) for gastric varices (GOV2/IGV1).\n' +
      '5. PRE-EMPTIVE TIPS: Within 72 hours if Child-Pugh B (active bleeding at endoscopy) or Child-Pugh C (score ≤13) or HVPG ≥20 mmHg — reduces 6-week mortality (NEJM 2010, Baveno VII Strong Recommendation).\n' +
      '6. BALLOON TAMPONADE: Sengstaken-Blakemore tube as BRIDGE only (max 24h) if endoscopy unavailable or failed — not definitive therapy.';

    if (input.hasGastricVarices) {
      acuteBleedManagement +=
        '\n\nGASTRIC VARICES (Baveno VII):\n' +
        '• GOV1 (extension of esophageal varices along lesser curve): EBL + cyanoacrylate injection.\n' +
        '• GOV2 (extension along greater curve) / IGV1 (isolated fundal): Cyanoacrylate injection preferred. BRTO (balloon-occluded retrograde transvenous obliteration) if gastrorenal shunt present — superior to TIPS for GOV2/IGV1 (BRTO trial). TIPS if no gastrorenal shunt or refractory.';
    }

    recommendedAgents.push(
      'Octreotide 50mcg IV bolus then 25–50mcg/hr x5 days',
      'Terlipressin 2mg IV Q4h x48h then 1mg Q4h (if available)',
      'Ceftriaxone 1g IV/day x7 days',
      'Cyanoacrylate (gastric varices — GOV2/IGV1)',
      'Carvedilol or propranolol (secondary prophylaxis after bleed control)'
    );
  }

  // ─── Secondary Prophylaxis ────────────────────────────────────────────────
  let secondaryProphylaxis = '';

  if (input.hasPriorVaricealBleeding) {
    secondaryProphylaxis =
      'Secondary prophylaxis (prevention of re-bleed) — Baveno VII Strong Recommendation:\n' +
      '• NSBB + EBL COMBINATION is standard of care (superior to either alone — Baveno VII).\n' +
      '• Start NSBB within 5 days of bleed (carvedilol 6.25mg/day → 12.5mg/day preferred; propranolol 20mg BID alternative).\n' +
      '• EBL every 2–4 weeks until variceal eradication, then endoscopy at 1–3 months, then every 6–12 months.\n' +
      '• TIPS for secondary prophylaxis: indicated if NSBB + EBL fails (rebleeding despite optimal medical/endoscopic therapy). TIPS reduces rebleeding to <10% vs ~30% with NSBB + EBL.\n' +
      '• Gastric varices (GOV2/IGV1): BRTO preferred if gastrorenal shunt present; TIPS if no shunt or refractory.';

    if (!input.isOnNSBB) {
      nextSteps.push('Start carvedilol 6.25mg/day for secondary prophylaxis');
    }
    if (!input.hasPriorEBL) {
      nextSteps.push('Schedule EBL for variceal eradication (secondary prophylaxis)');
    }
  }

  // ─── Ascites Management ───────────────────────────────────────────────────
  let ascitesManagement = '';
  let sbpProphylaxis = '';

  if (input.ascitesGrade === 'none') {
    ascitesManagement = 'No ascites. Maintain low-sodium diet (<2g/day). Monitor with 6-monthly ultrasound. NSBB for portal hypertension if varices present.';
  } else if (input.ascitesGrade === 'grade1') {
    ascitesManagement =
      'Grade 1 ascites (detectable by ultrasound only): sodium restriction (<2g/day). ' +
      'Low-dose spironolactone 50–100mg/day. Avoid NSAIDs, aminoglycosides, ACE inhibitors. ' +
      'Monitor renal function and electrolytes every 2–4 weeks.';
    recommendedAgents.push('Spironolactone 50–100mg/day (start low, titrate)');
  } else if (input.ascitesGrade === 'grade2') {
    ascitesManagement =
      'Grade 2 ascites (moderate): sodium restriction + diuretics. ' +
      'Spironolactone 100mg/day + furosemide 40mg/day (5:2 ratio — EASL guideline). ' +
      'Titrate every 3–5 days: max spironolactone 400mg/day + furosemide 160mg/day. ' +
      'Target weight loss: 0.5kg/day (no peripheral edema) or 1kg/day (with peripheral edema). ' +
      'Avoid hyponatremia (Na <125 mEq/L → hold diuretics). Avoid renal impairment (Cr increase >2mg/dL → hold diuretics).';
    recommendedAgents.push(
      'Spironolactone 100mg/day + furosemide 40mg/day (5:2 ratio)',
      'Titrate to spironolactone 400mg + furosemide 160mg/day max'
    );
  } else if (input.ascitesGrade === 'grade3') {
    ascitesManagement =
      'Grade 3 (tense) ascites: large-volume paracentesis (LVP) — remove all ascites in single session. ' +
      'IV albumin 6–8g per liter removed (prevents post-paracentesis circulatory dysfunction — PPCD). ' +
      'After LVP: restart diuretics at lower dose. ' +
      'If recurrent tense ascites: consider TIPS (Child-Pugh ≤11, MELD <15, no HE) — TIPS superior to LVP for refractory ascites (CONFIRM trial). ' +
      'Sodium restriction <2g/day. Avoid nephrotoxins.';
    recommendedAgents.push(
      'IV albumin 6–8g per liter of ascites removed (PPCD prevention)',
      'Spironolactone + furosemide after LVP (restart at lower dose)'
    );
    nextSteps.push('Large-volume paracentesis with IV albumin replacement');
  } else if (input.ascitesGrade === 'refractory') {
    ascitesManagement =
      'REFRACTORY ASCITES (failed spironolactone 400mg + furosemide 160mg, or diuretic-intolerant):\n' +
      '• TIPS (transjugular intrahepatic portosystemic shunt): first-line for refractory ascites in eligible patients. ' +
      'Criteria: Child-Pugh ≤11, MELD <18–20, no HE Grade ≥2, no severe cardiopulmonary disease. ' +
      'TIPS reduces portal pressure, controls ascites in 70–80%, improves survival vs LVP (meta-analysis). ' +
      '• Serial LVP + albumin: for patients not eligible for TIPS. Every 2–4 weeks. ' +
      '• Tolvaptan (V2 receptor antagonist): for hyponatremic ascites (Na <130 mEq/L) — short-term use only (hepatotoxicity risk). ' +
      '• Alfapump (automated low-flow ascites pump): investigational — POSEIDON trial ongoing. ' +
      '• Liver transplant evaluation: refractory ascites is a decompensation event — MELD exception points may apply.';
    nextSteps.push('TIPS evaluation (IR consultation)', 'Liver transplant evaluation');
    recommendedAgents.push(
      'IV albumin 6–8g/L removed (serial LVP)',
      'Tolvaptan 15mg/day (hyponatremia — short-term only)'
    );
  }

  // SBP Prophylaxis
  if (input.hasPriorSBP || input.ascitesProteinLow || input.meldCategory === 'very_high') {
    sbpProphylaxis =
      'SBP PROPHYLAXIS INDICATED (EASL 2023 / AASLD 2024):\n' +
      '• Prior SBP: norfloxacin 400mg/day indefinitely (or TMP-SMX DS daily as alternative).\n' +
      '• Ascitic protein <1.5g/dL + Child-Pugh ≥9 or bilirubin ≥3 or renal impairment: norfloxacin 400mg/day.\n' +
      '• Acute variceal bleed: ceftriaxone 1g/day x7 days (covers SBP prevention during bleed episode).\n' +
      '• IV albumin: 1.5g/kg day 1 + 1g/kg day 3 during SBP episode (prevents HRS — SORT trial).';
    recommendedAgents.push(
      'Norfloxacin 400mg/day (primary SBP prophylaxis)',
      'TMP-SMX DS daily (alternative to norfloxacin)'
    );
  } else {
    sbpProphylaxis = 'No current SBP prophylaxis indication. Reassess if ascites protein <1.5g/dL, prior SBP, or MELD ≥20.';
  }

  // ─── Hepatic Encephalopathy ───────────────────────────────────────────────
  let heManagement = '';

  if (input.heGrade === 'none' && !input.hasPriorHEEpisode) {
    heManagement = 'No hepatic encephalopathy. Covert HE screening with psychometric tests (EncephalApp Stroop, PHES) recommended in cirrhotic patients — affects driving and quality of life.';
  } else if (input.heGrade === 'minimal' || input.heGrade === 'grade1') {
    heManagement =
      'Covert/Minimal HE (Grade 1): lactulose 15–30mL BID–TID (titrate to 2–3 soft stools/day). ' +
      'Rifaximin 550mg BID if lactulose intolerant or recurrent HE. ' +
      'Identify and correct precipitants: infection, GI bleed, constipation, electrolyte disturbance, benzodiazepines/opioids. ' +
      'Driving restriction counseling. Nutritional support (1.2–1.5g/kg/day protein — do NOT restrict protein in HE).';
    recommendedAgents.push(
      'Lactulose 15–30mL BID–TID (titrate to 2–3 soft stools/day)',
      'Rifaximin 550mg BID (recurrent HE or lactulose intolerant)'
    );
  } else if (input.heGrade === 'grade2') {
    heManagement =
      'Overt HE (Grade 2): lactulose 30–45mL Q1–2h until bowel movement, then TID maintenance. ' +
      'Rifaximin 550mg BID (add to lactulose for recurrent HE — reduces hospitalizations 58% — NEJM 2010). ' +
      'Identify and treat precipitant urgently. ' +
      'Zinc supplementation (zinc deficiency common in cirrhosis). ' +
      'TIPS contraindicated if uncontrolled HE — assess HE before TIPS.';
    recommendedAgents.push(
      'Lactulose 30–45mL Q1–2h (acute), then TID maintenance',
      'Rifaximin 550mg BID (add for recurrent HE)',
      'Zinc acetate 50mg BID (adjunct)'
    );
  } else if (input.heGrade === 'grade3' || input.heGrade === 'grade4') {
    heManagement =
      'Severe HE (Grade 3–4): ICU admission, airway protection (intubate if GCS ≤8). ' +
      'Lactulose via NG tube (30mL Q2h until bowel movement). ' +
      'Rifaximin 550mg BID via NG. ' +
      'Identify precipitant (infection most common — blood cultures, urine culture, diagnostic paracentesis). ' +
      'Avoid sedatives/benzodiazepines. ' +
      'Liver transplant evaluation — severe refractory HE is a transplant indication. ' +
      'TIPS is CONTRAINDICATED in HE Grade 3–4 (absolute contraindication — worsens HE).';
  }

  if (input.hasPriorHEEpisode && !input.isOnRifaximin) {
    nextSteps.push('Start rifaximin 550mg BID for secondary HE prophylaxis (reduces recurrence 58%)');
    recommendedAgents.push('Rifaximin 550mg BID (secondary HE prophylaxis)');
  }

  // ─── HRS Management ───────────────────────────────────────────────────────
  let hrsManagement = '';

  if (!input.hasHRS) {
    hrsManagement = 'No HRS identified. Monitor renal function closely — AKI in cirrhosis is common (infections, diuretics, NSAIDs). Avoid nephrotoxins. Albumin infusion during SBP and large-volume paracentesis.';
  } else if (input.hrsType === 'HRS_AKI') {
    hrsManagement =
      'HRS-AKI (Hepatorenal Syndrome — Acute Kidney Injury):\n' +
      '• STOP diuretics, NSAIDs, nephrotoxins, beta-blockers.\n' +
      '• IV albumin 1g/kg/day (max 100g) x2 days (volume expansion challenge).\n' +
      '• If no response: terlipressin 0.5mg IV Q4h → titrate to 2mg Q4h (CONFIRM trial: 32% HRS reversal vs 17% placebo). ' +
      'Terlipressin FDA-approved 2022 for HRS-AKI.\n' +
      '• Alternative if terlipressin unavailable: norepinephrine 0.5–3mg/hr IV + albumin 20–40g/day.\n' +
      '• Midodrine 7.5mg TID + octreotide 100–200mcg SC TID + albumin: outpatient option if terlipressin/NE unavailable.\n' +
      '• Liver transplant is the only definitive treatment — urgent evaluation required.\n' +
      '• TIPS as bridge to transplant: may improve renal function in HRS but limited data.';
    recommendedAgents.push(
      'Terlipressin 0.5–2mg IV Q4h (FDA-approved 2022 — CONFIRM trial)',
      'Norepinephrine 0.5–3mg/hr IV + albumin (if terlipressin unavailable)',
      'IV albumin 1g/kg/day x2 days (volume challenge)',
      'Midodrine 7.5mg TID + octreotide 100–200mcg SC TID (outpatient alternative)'
    );
  } else {
    hrsManagement =
      'HRS-CKD (Chronic Kidney Disease in cirrhosis): ' +
      'Optimize fluid status, avoid nephrotoxins. Renal replacement therapy as bridge to liver transplant. ' +
      'Simultaneous liver-kidney transplant (SLK) if CKD ≥90 days or GFR <25 mL/min — UNOS criteria.';
  }

  // ─── TIPS Assessment ──────────────────────────────────────────────────────
  let tipsIndication = '';
  let tipsContraindicationAssessment = '';

  const tipsContras = input.tipsContraindications ?? [];
  const hasHEContraindication =
    tipsContras.includes('he_grade3_4') ||
    input.heGrade === 'grade3' ||
    input.heGrade === 'grade4';

  const tipsIndicationList: string[] = [];
  if (input.hasActiveVaricealBleeding && (input.childPughClass === 'B' || input.childPughClass === 'C')) {
    tipsIndicationList.push('Pre-emptive TIPS (within 72h) — acute variceal bleed in Child-Pugh B/C');
  }
  if (input.hasPriorVaricealBleeding && input.isOnNSBB && input.hasPriorEBL) {
    tipsIndicationList.push('Secondary prophylaxis TIPS — rebleeding despite NSBB + EBL');
  }
  if (input.ascitesGrade === 'refractory' || input.isDiureticRefractory) {
    tipsIndicationList.push('Refractory ascites — TIPS preferred over serial LVP (if MELD <18–20)');
  }
  if (
    input.pvtExtent !== 'none' &&
    input.pvtExtent !== 'cavernous_transformation' &&
    input.hasAnticoagulationContraindication
  ) {
    tipsIndicationList.push('PVT with anticoagulation contraindication — TIPS for portal decompression');
  }
  if (input.hasHRS && input.hrsType === 'HRS_AKI') {
    tipsIndicationList.push('HRS-AKI — TIPS as bridge to transplant (limited evidence, case-by-case)');
  }

  tipsIndication =
    tipsIndicationList.length > 0
      ? 'TIPS INDICATIONS IDENTIFIED:\n' + tipsIndicationList.map((t, i) => `${i + 1}) ${t}`).join('\n')
      : 'No current TIPS indication. Reassess if refractory ascites, rebleeding despite NSBB + EBL, or pre-emptive TIPS criteria met.';

  const contraList: string[] = [];
  if (hasHEContraindication) contraList.push('Uncontrolled HE Grade 3–4 (absolute contraindication)');
  if (tipsContras.includes('heart_failure')) contraList.push('Congestive heart failure (TIPS increases right heart preload)');
  if (tipsContras.includes('severe_pulmonary_htn')) contraList.push('Severe pulmonary arterial hypertension (mean PAP >45 mmHg)');
  if (tipsContras.includes('uncontrolled_infection')) contraList.push('Uncontrolled systemic infection / sepsis');
  if (tipsContras.includes('biliary_obstruction')) contraList.push('Biliary obstruction (relative — may worsen biliary-venous fistula)');
  if (input.childPughClass === 'C' && input.meldCategory === 'very_high') {
    contraList.push('Child-Pugh C + MELD ≥20: high procedural mortality — transplant preferred over TIPS');
  }

  tipsContraindicationAssessment =
    contraList.length > 0
      ? 'TIPS CONTRAINDICATIONS PRESENT:\n' + contraList.map((c, i) => `${i + 1}) ${c}`).join('\n') +
        '\n\nReview contraindications with hepatology + IR. Transplant evaluation should be prioritized.'
      : 'No absolute TIPS contraindications identified. Proceed with hepatology + IR evaluation if TIPS indicated.';

  // ─── Transplant Consideration ─────────────────────────────────────────────
  let transplantConsideration = '';
  const transplantIndicators: string[] = [];

  if (input.meldCategory === 'very_high') transplantIndicators.push('MELD ≥20');
  if (input.ascitesGrade === 'refractory') transplantIndicators.push('Refractory ascites');
  if (input.hasPriorVaricealBleeding) transplantIndicators.push('Prior variceal hemorrhage');
  if (input.hasPriorHEEpisode) transplantIndicators.push('Prior hepatic encephalopathy episode');
  if (input.hasSBP || input.hasPriorSBP) transplantIndicators.push('Spontaneous bacterial peritonitis');
  if (input.hasHRS) transplantIndicators.push('Hepatorenal syndrome');

  if (transplantIndicators.length > 0) {
    transplantConsideration =
      'LIVER TRANSPLANT EVALUATION RECOMMENDED:\n' +
      'Decompensation events present: ' + transplantIndicators.join(', ') + '.\n' +
      'Refer to transplant center. MELD-Na score determines listing priority. ' +
      'All interventions (TIPS, anticoagulation, paracentesis) are bridges to transplant — do not delay evaluation.';
    if (input.isTransplantCandidate && !input.isListedForTransplant) {
      nextSteps.push('Urgent liver transplant evaluation and listing');
    }
  } else {
    transplantConsideration =
      'No current decompensation events. Maintain surveillance per compensated cirrhosis guidelines. ' +
      'Reassess transplant candidacy if decompensation occurs.';
  }

  // ─── Monitoring Plan ──────────────────────────────────────────────────────
  const monitoringPlan =
    'PORTAL HYPERTENSION MONITORING (Baveno VII / AASLD 2024):\n' +
    '• Ultrasound + AFP: every 6 months (HCC surveillance in cirrhosis).\n' +
    '• Doppler ultrasound of portal vein: every 3–6 months if PVT present (assess recanalization).\n' +
    '• Upper endoscopy: per variceal grade (see above). Baveno VII: non-invasive criteria can replace endoscopy in low-risk patients.\n' +
    '• Renal function + electrolytes: every 1–3 months (diuretics, HRS risk).\n' +
    '• Serum sodium: monitor closely — hyponatremia (Na <130) is a MELD-Na component and transplant indicator.\n' +
    '• MELD-Na: reassess every 3–6 months (or more frequently if decompensating).\n' +
    '• Nutritional assessment: DEXA scan for sarcopenia (common in cirrhosis — worsens prognosis). Target 1.2–1.5g/kg/day protein.';

  // ─── Primary Recommendation ───────────────────────────────────────────────
  const primaryRecommendation =
    input.hasActiveVaricealBleeding
      ? 'ACUTE VARICEAL HEMORRHAGE: Activate variceal bleed protocol — octreotide + ceftriaxone + urgent endoscopy (EBL). Pre-emptive TIPS within 72h if Child-Pugh B/C (Baveno VII Strong Recommendation).'
      : input.hasIntestinalIschemia
      ? 'INTESTINAL ISCHEMIA with PVT: Emergency anticoagulation + surgical/IR consultation. CT angiography of mesenteric vessels.'
      : input.hasSBP
      ? 'SPONTANEOUS BACTERIAL PERITONITIS: IV cefotaxime/ceftriaxone + IV albumin protocol (SORT trial). Initiate long-term SBP prophylaxis after resolution.'
      : input.hasHRS && input.hrsType === 'HRS_AKI'
      ? 'HRS-AKI: Hold diuretics/nephrotoxins, IV albumin challenge, terlipressin (FDA-approved 2022). Urgent liver transplant evaluation.'
      : input.heGrade === 'grade3' || input.heGrade === 'grade4'
      ? 'SEVERE HEPATIC ENCEPHALOPATHY (Grade 3–4): ICU, airway protection, lactulose via NG, rifaximin. TIPS contraindicated. Transplant evaluation.'
      : input.pvtExtent !== 'none' && input.pvtExtent !== 'cavernous_transformation' && input.pvtAcuity === 'acute'
      ? 'ACUTE PVT: Anticoagulation (LMWH or DOAC) — start immediately. 40–80% recanalization with early treatment (AASLD 2024). Thrombophilia workup.'
      : input.ascitesGrade === 'refractory' || input.isDiureticRefractory
      ? 'REFRACTORY ASCITES: TIPS evaluation (if MELD <18–20, no HE) — superior to serial LVP. Serial LVP + albumin if TIPS not feasible. Transplant evaluation.'
      : input.varicesGrade === 'large' || input.hasRedWaleMarks
      ? 'HIGH-RISK VARICES: Primary prophylaxis with carvedilol (Baveno VII preferred) or EBL. Target HR 55–60 bpm on NSBB.'
      : 'Portal hypertension management: individualized approach based on Baveno VII framework. Assess varices, ascites, PVT, and HE systematically.';

  // ─── Evidence Level ───────────────────────────────────────────────────────
  const evidenceLevel: 'A' | 'B' | 'C' =
    input.hasActiveVaricealBleeding || input.hasSBP || input.hasHRS
      ? 'A'
      : input.ascitesGrade !== 'none' || input.pvtExtent !== 'none'
      ? 'A'
      : 'B';

  // ─── Rationale ────────────────────────────────────────────────────────────
  const rationale =
    `Clinical scenario: ${input.primaryScenario.replace(/_/g, ' ')}. ` +
    `Cirrhosis: ${input.hasCirrhosis ? `Yes (Child-Pugh ${input.childPughClass}, MELD ${input.meldCategory})` : 'No'}. ` +
    `PVT: ${input.pvtExtent.replace(/_/g, ' ')} (${input.pvtAcuity}). ` +
    `Varices: ${input.varicesGrade}${input.hasRedWaleMarks ? ' + red wale marks' : ''}. ` +
    `Ascites: ${input.ascitesGrade}. ` +
    `HE: Grade ${input.heGrade}. ` +
    `TIPS candidate: ${input.hasTIPSContraindication ? 'No (contraindication)' : 'Evaluate'}. ` +
    `Transplant listed: ${input.isListedForTransplant ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation,
    pvtManagement,
    anticoagulationPlan,
    varicesProphylaxis,
    acuteBleedManagement,
    secondaryProphylaxis,
    ascitesManagement,
    sbpProphylaxis,
    heManagement,
    hrsManagement,
    tipsIndication,
    tipsContraindicationAssessment,
    transplantConsideration,
    monitoringPlan,
    urgentFlags,
    recommendedAgents,
    nextSteps,
    evidenceLevel,
    rationale,
    references: [
      {
        citation:
          'de Franchis R, Bosch J, Garcia-Tsao G, et al. Baveno VII — Renewing consensus in portal hypertension. J Hepatol. 2022;76(4):959-974.',
        pmid: '35120736',
        url: 'https://pubmed.ncbi.nlm.nih.gov/35120736/',
      },
      {
        citation:
          'Baveno VII Faculty. Expanding consensus in portal hypertension: Report of the Baveno VII Consensus Workshop. J Hepatol. 2024 (Update).',
        url: 'https://www.baveno.net',
      },
      {
        citation:
          'Garcia-Tsao G, Abraldes JG, Berzigotti A, Bosch J. Portal hypertensive bleeding in cirrhosis: Risk stratification, diagnosis, and management: 2016 practice guidance by the American Association for the Study of Liver Diseases. Hepatology. 2017;65(1):310-335.',
        pmid: '27786365',
        url: 'https://pubmed.ncbi.nlm.nih.gov/27786365/',
      },
      {
        citation:
          'EASL Clinical Practice Guidelines for the management of patients with decompensated cirrhosis. J Hepatol. 2018;69(2):406-460. (Updated 2023)',
        pmid: '29653741',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29653741/',
      },
      {
        citation:
          'EASL Clinical Practice Guidelines: Vascular diseases of the liver. J Hepatol. 2016;64(1):179-202. (Updated 2024)',
        pmid: '26516032',
