      },
      {
        citation:
          'Northup PG, Garcia-Pagan JC, Garcia-Tsao G, et al. Vascular Liver Disorders, Portal Vein Thrombosis, and the Coagulation System in Liver Disease: 2020 Practice Guidance by the American Association for the Study of Liver Diseases. Hepatology. 2021;73(1):366-413.',
        pmid: '33219529',
        url: 'https://pubmed.ncbi.nlm.nih.gov/33219529/',
      },
      {
        citation:
          'Wong F, Pappas SC, Boyer TD, et al. Terlipressin plus Albumin for the Treatment of Type 1 Hepatorenal Syndrome–Acute Kidney Injury (CONFIRM Trial). N Engl J Med. 2021;384(9):818-828.',
